sealed class ManualClock(DateTimeOffset start) : TimeProvider
{
    public DateTimeOffset Now { get; set; } = start;
    public override DateTimeOffset GetUtcNow() => Now;
}

sealed class Token(DateTimeOffset expiresAt, TimeProvider time)
{
    public bool IsExpired => time.GetUtcNow() > expiresAt;
}

var stub = new StubRates(2m);
var spy = new SpyAudit();
var service = new Converter(stub, spy);

Console.WriteLine(service.ToEur(100m));
Console.WriteLine(service.ToEur(0m));
Console.WriteLine(spy.Calls.Count);
Console.WriteLine(string.Join("|", spy.Calls));

interface IRates { decimal UsdToEur(); }
interface IAudit { void Record(string message); }

class StubRates(decimal rate) : IRates { public decimal UsdToEur() => rate; }
class SpyAudit : IAudit
{
    public List<string> Calls { get; } = new();
    public void Record(string message) => Calls.Add(message);
}

class Converter(IRates rates, IAudit audit)
{
    public decimal ToEur(decimal usd)
    {
        if (usd == 0) return 0;
        var eur = usd * rates.UsdToEur();
        audit.Record($"{usd}->{eur}");
        return eur;
    }
}

